def max_coins(nums):
    values = [1] + list(nums) + [1]
    n = len(values)
    table = [[0] * n for _ in range(n)]
    for width in range(2, n):
        for left in range(0, n - width):
            right = left + width
            best = 0
            for k in range(left + 1, right):
                score = table[left][k] + table[k][right] + values[left] * values[k] * values[right]
                if score > best:
                    best = score
            table[left][right] = best
    return table[0][n - 1]

bruteForceCode:
def max_coins(nums):
    def burst(standing):
        if not standing:
            return 0
        best = 0
        for k in range(len(standing)):
            left = standing[k - 1] if k > 0 else 1
            right = standing[k + 1] if k + 1 < len(standing) else 1
            total = left * standing[k] * right + burst(standing[:k] + standing[k + 1:])
            if total > best:
                best = total
        return best
    return burst(list(nums))
